async function main() {
  if(records.length!==TOTAL)throw new Error(`Slide count ${records.length} != ${TOTAL}`);
  const output=path.join(__dirname,'output');fs.mkdirSync(output,{recursive:true});
  const name=MAIN_ONLY ? 'FINAL_PRESENTATION_MAIN_ONLY' : 'FINAL_PRESENTATION';
  fs.writeFileSync(path.join(output,`${name}_NOTES.json`),JSON.stringify(records,null,2));
  fs.writeFileSync(path.join(output,`${name}_SPEAKER_NOTES.md`),
    '# Presentation speaker notes\n\nSuggested main-story duration: approximately 8–10 minutes; adapt to the actual time limit. Slides 16–23 are backup.\n\n'+
    records.map(r=>`## ${r.number}. ${r.title}\n\n${r.notes}\n`).join('\n'));
  await pptx.writeFile({fileName:path.join(output,`${name}.pptx`)});
  console.log(`Created ${name}.pptx (${records.length} slides)`);
}
main().catch(error=>{console.error(error);process.exitCode=1;});
